--[[
How We Got the Data

Last Validated
	2026-10-05, TBC Anniversary 2.5.6.69795

Notes
	- Built from wago.tools: ItemEffect (TriggerType 1, on equip) to SpellEffect auras for ITEM_STAT_FLAGS, and ItemRandomProperties / ItemRandomSuffix to SpellItemEnchantment (type 3 an equip spell, type 5 a stat) for RANDOM_SUFFIX_STAT_FLAGS. Equippable items only (InventoryType set).
	- Auras read: 29 MOD_STAT (misc 0-4, -1 for all), 13 MOD_DAMAGE_DONE with a magic school (Spell Power), 135 MOD_HEALING_DONE (Healing), 99 MOD_ATTACK_POWER (melee Attack Power; ranged-only 124 is left out), 52/57/71/290/552 crit chance, 54/55 hit chance, 85 MOD_POWER_REGEN on mana (Mana Per 5), and 189 MOD_RATING with a crit or hit rating bit.
	- Base primary stats aren't listed: GetItemStats reports those on every client, and Features/Automated-Rolls.lua reads it alongside these tables.
	- Generated 2026-10-05 by a script walking the tables above; regenerate against a new build rather than editing by hand.
	- TBC's ratings are mostly real stats (GetItemStats reports them); the table catches the ones still worded as equip spells. Random suffixes from ItemRandomSuffix carry negative ids in the link.

SQL (CMaNGOS)
	TODO: Add SQL Query

Wowhead
	Not used: the tables above come straight from the client's own data.
]]
